canvas.onpointerup=endPointer;canvas.onpointercancel=endPointer;canvas.onlostpointercapture=endPointer;
canvas.addEventListener('wheel',e=>{e.preventDefault();view.zoom=Math.max(.2,Math.min(4,view.zoom*(e.deltaY<0?1.08:.92)));zoomUI();},{passive:false});
$('addCard').ondragstart=e=>{e.dataTransfer.setData('text/plain','snowflake-37');};canvas.ondragover=e=>e.preventDefault();canvas.ondrop=e=>{e.preventDefault();if(e.dataTransfer.getData('text/plain')==='snowflake-37'){let p=pointer(e);addBoard(inverse(p.x,p.y));}};
$('addBtn').onclick=()=>addBoard();$('addCard').onclick=()=>addBoard();$('rotateBtn').onclick=()=>{let b=state.boards.find(b=>b.id===selected);if(b){snapshot();b.rotation=(b.rotation+30)%360;changed();}};$('copyBtn').onclick=()=>{let b=state.boards.find(b=>b.id===selected);if(b){let rot=b.rotation;addBoard({x:b.x+90,y:b.y});state.boards.at(-1).rotation=rot;changed();}};$('deleteBtn').onclick=removeBoard;$('removeBtn').onclick=removeBoard;
$('undoBtn').onclick=undo;$('redoBtn').onclick=redo;$('labelsBtn').onclick=()=>{labels=!labels;$('labelsBtn').classList.toggle('on',labels);};$('wiresBtn').onclick=()=>{wires=!wires;$('wiresBtn').classList.toggle('on',wires);};
$('zoomIn').onclick=()=>{view.zoom=Math.min(4,view.zoom*1.2);zoomUI();};$('zoomOut').onclick=()=>{view.zoom=Math.max(.2,view.zoom/1.2);zoomUI();};$('fitBtn').onclick=fit;
function playUI(){$('playBtn').textContent=playing?'Ⅱ':'▶';$('playBtn').setAttribute('aria-label',playing?'暂停':'播放');}
async function togglePlayback(){playing=!playing;try{if(playing&&soundEnabled&&state.scene.music)await player.restore(state.scene.music);}catch(e){soundEnabled=false;toast(e.message);}syncAudio();playUI();}
$('playBtn').onclick=togglePlayback;$('resetTime').onclick=()=>{time=0;syncAudio();};$('timeline').oninput=e=>{playing=false;time=+e.target.value/1000;player.stop();playUI();soundUI();};

$('brightness').onpointerdown=()=>snapshot();$('brightness').onkeydown=e=>{if(e.key.startsWith('Arrow'))snapshot();};$('brightness').oninput=e=>{state.scene.brightness=+e.target.value;$('brightnessText').textContent=e.target.value+'%';persist();};$('brightness').onchange=syncUI;
$('duration').onchange=e=>{snapshot();state.scene.duration=+e.target.value;time=0;changed();};$('projectName').maxLength=80;$('projectName').onchange=e=>{snapshot();state.name=e.target.value.trim()||'未命名的光';changed();};
$('pinSelect').innerHTML=Object.entries(PIN_MAP).map(([p,n])=>`<option value="${p}">GP${p} — J2 第 ${n} 脚${p==='20'?'（默认）':''}</option>`).join('');$('pinSelect').onchange=e=>{snapshot();state.pin=+e.target.value;changed();};
document.querySelectorAll('[data-layout]').forEach(b=>b.onclick=()=>applyLayout(b.dataset.layout));document.querySelectorAll('[data-tab]').forEach(b=>b.onclick=()=>{document.querySelectorAll('[data-tab]').forEach(t=>t.classList.toggle('active',t===b));$('boardsTab').hidden=b.dataset.tab!=='boards';$('presetsTab').hidden=b.dataset.tab!=='presets';});
function renderPresetList(){if(!$('presetList'))return;$('presetList').replaceChildren();PRESETS.forEach((p,i)=>{if(presetCategory!=='全部'&&p.category!==presetCategory)return;let b=document.createElement('button');b.className='preset-card'+(state.scene.name===p.name?' selected':'');b.innerHTML=`<span style="background:${p.swatch}">${p.musicHint?'♫':'❄'}</span><div><strong>${p.name}</strong><small>${p.description}</small><span class="preset-index">${String(i+1).padStart(2,'0')} / 20 · ${p.category}${p.musicHint?' · 自带配乐':''}</span></div>`;b.onclick=async()=>{if(musicBusy){toast('正在处理配乐，请稍候');return;}snapshot();let m=state.scene.music;state.scene=validateScene(p,state.boards.length);if(m&&!p.musicHint){state.scene.music=m;state.scene.duration=m.duration;}time=0;playing=true;playUI();changed();if(p.musicHint)await activateMusic({source:'demo',track:'groove',mode:p.musicHint,duration:state.scene.duration,offset:0});toast('已应用「'+p.name+'」');};$('presetList').append(b);});}
document.querySelectorAll('[data-category]').forEach(b=>b.onclick=()=>{presetCategory=b.dataset.category;document.querySelectorAll('[data-category]').forEach(x=>x.classList.toggle('active',x===b));renderPresetList();});
$('referencesBtn').onclick=()=>$('referencesDialog').showModal();
$('glowBtn').onclick=()=>{glowMode=true;$('exposure').disabled=false;$('glowBtn').classList.add('active');$('rawBtn').classList.remove('active');};$('rawBtn').onclick=()=>{glowMode=false;$('exposure').disabled=true;$('rawBtn').classList.add('active');$('glowBtn').classList.remove('active');};$('exposure').oninput=e=>exposure=+e.target.value;
$('musicBtn').onclick=()=>{const m=state.scene.music;$('musicSource').value=m?(m.source==='demo'?m.track:'upload'):'bells';$('musicMode').value=m?.mode||'pulse';if(!Array.from($('musicDuration').options).some(o=>+o.value===state.scene.duration))$('musicDuration').add(new Option(state.scene.duration+' 秒',state.scene.duration));$('musicDuration').value=state.scene.duration;$('audioOffset').value=m?.offset||0;$('uploadControls').hidden=$('musicSource').value!=='upload';$('musicDialog').showModal();};
$('musicSource').onchange=()=>{$('uploadControls').hidden=$('musicSource').value!=='upload';};
$('audioFile').onchange=async e=>{const file=e.target.files[0];if(!file)return;musicBusy=true;$('applyMusic').disabled=true;$('musicStatus').textContent='正在本地解码音频…';try{let duration=await player.loadFile(file);$('audioFileInfo').textContent=`${file.name} · ${duration.toFixed(1)} 秒 · 本地已载入`;$('musicStatus').textContent='选择片段起点与时长，再应用试听。';}catch(err){$('musicStatus').textContent=err.message;}finally{musicBusy=false;$('applyMusic').disabled=false;}};
async function activateMusic(config){if(musicBusy)return;musicBusy=true;const before=JSON.stringify(state);$('applyMusic').disabled=true;$('musicStatus').textContent='正在分析音量和三个频段…';try{const m=await player.prepare(config);if(JSON.stringify(state)!==before)throw Error('分析期间项目已改变，请重新应用配乐');snapshot();state.scene.music=m;state.scene.duration=config.duration;time=0;playing=true;soundEnabled=true;playUI();changed();$('musicStatus').textContent='已应用；播放、暂停和时间轴与音乐同步。';$('musicDialog').close();}catch(e){$('musicStatus').textContent=e.message;toast(e.message);}finally{musicBusy=false;$('applyMusic').disabled=false;}}
$('applyMusic').onclick=()=>activateMusic({source:$('musicSource').value==='upload'?'upload':'demo',track:$('musicSource').value,duration:+$('musicDuration').value,offset:+$('audioOffset').value,mode:$('musicMode').value});
$('removeMusic').onclick=()=>{snapshot();delete state.scene.music;player.stop();changed();$('musicDialog').close();toast('配乐已移除');};$('musicVolume').oninput=e=>player.volume(+e.target.value/100);$('audioDownload').onclick=()=>{try{download(player.wav(),'snowflake-music.wav','audio/wav');}catch(e){toast(e.message);}};

$('miniSnow').innerHTML=`<g transform="translate(60,55) scale(1.05)"><path d="M${OUTLINE.map(p=>p.join(',')).join('L')}Z" fill="#d5e2c9" stroke="#b5c8a5" stroke-width=".65"/>${LEDS.map(l=>`<rect x="${l.x-1.7}" y="${l.y-1.7}" width="3.4" height="3.4" rx=".4" fill="#ffffdc" stroke="#abc190" stroke-width=".6"/><circle cx="${l.x}" cy="${l.y}" r=".8" fill="#9ba989"/>`).join('')}</g>`;
function download(data,name,type='application/octet-stream'){let url=URL.createObjectURL(new Blob([data],{type})),a=document.createElement('a');a.href=url;a.download=name;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),10000);}
$('saveBtn').onclick=()=>{download(JSON.stringify(state,null,2),'snowflake-project.json','application/json');toast('项目已导出，不包含 API 密钥');};$('importBtn').onclick=()=>$('importInput').click();$('importInput').onchange=async e=>{try{let file=e.target.files[0];if(!file)return;if(file.size>400000)throw Error('项目文件过大');let p=validateProject(JSON.parse(await file.text()));player.stop();snapshot();state=p;selected=state.boards[0].id;time=0;changed();fit();toast('项目已导入');}catch(err){toast('导入失败：'+err.message);}finally{e.target.value='';}};
for(let id of ['guideBtn','hardwareBtn','downloadBtn'])$(id).onclick=()=>{$('buildStatus').textContent='';$('hardwareDialog').showModal();};
$('sourceBtn').onclick=()=>{let a=document.createElement('a');a.href='snowflake-firmware-source.zip';a.download='snowflake-firmware-source.zip';document.body.append(a);a.click();a.remove();};
$('buildBtn').onclick=async()=>{const button=$('buildBtn');button.disabled=true;$('buildProgress').hidden=false;try{let s=clone(state);$('buildStatus').textContent='正在生成与预览一致的像素帧…';let r=await fetch('runtime.bin');if(!r.ok)throw Error('固件运行时下载失败');let binary=new Uint8Array(await r.arrayBuffer());let uf2=await buildUF2(s.scene,s.boards,s.pin,binary,p=>{$('buildProgress').value=p;$('buildStatus').textContent=`正在打包 ${s.boards.length*37} 颗灯珠 · ${Math.round(p*100)}%`;});download(uf2,'snowflake-gp'+s.pin+'.uf2');$('buildStatus').textContent=`已生成 ${(uf2.length/1024).toFixed(0)} KB UF2 · ${s.scene.duration} 秒循环 · GP${s.pin}。拖入 RPI-RP2 即可烧录；实物效果待验证。`;toast('UF2 已生成并开始下载');}catch(e){$('buildStatus').textContent='生成失败：'+e.message;}finally{button.disabled=false;$('buildProgress').hidden=true;}};
// Gemini requests use the user's key in page memory only. Never eval model output.
$('apiBtn').onclick=()=>$('apiDialog').showModal();$('clearKey').onclick=()=>{apiKey='';$('apiKey').value='';$('aiNote').textContent='未连接 API 时，可直接体验左侧灵感灯效。';$('apiBtn').textContent='连接 Gemini';$('apiBtn').classList.remove('connected');$('apiStatus').textContent='已断开，密钥已从页面内存清除。';};
async function googleRequest(path,key,body){let res;try{res=await fetch('https://generativelanguage.googleapis.com/v1beta/'+path,{method:body?'POST':'GET',headers:{'x-goog-api-key':key,...(body?{'Content-Type':'application/json'}:{})},...(body?{body:JSON.stringify(body)}:{}),signal:AbortSignal.timeout(90000)});}catch(e){throw Error(e.name==='TimeoutError'?'请求超时，请重试':'无法连接 Google API，请检查网络和浏览器请求限制');}let json=await res.json().catch(()=>({}));if(!res.ok){const msg=res.status===401||res.status===403?'密钥无效或权限不足':res.status===429?'请求频率或额度已用尽':res.status===404?'模型不可用，请选择其他模型':'Google API 请求失败';throw Error(msg+'（'+res.status+'）');}return json;}
$('connectKey').onclick=async()=>{let key=$('apiKey').value.trim(),btn=$('connectKey');if(!key){$('apiStatus').textContent='请先输入 Gemini API 密钥';return;}btn.disabled=true;$('apiStatus').textContent='正在验证密钥并读取可用模型…';try{let result=await googleRequest('models?pageSize=1000',key);let models=(result.models||[]).filter(m=>m.supportedGenerationMethods?.includes('generateContent')).map(m=>m.name.replace(/^models\//,''));$('modelList').replaceChildren(...models.map(m=>new Option(m,m)));let chosen=$('modelInput').value.trim().replace(/^models\//,'');if(!models.includes(chosen)){chosen=models.find(m=>/flash/.test(m)&&!/(image|audio|tts|live)/.test(m))||models[0];if(!chosen)throw Error('该密钥没有可用的文本生成模型');$('modelInput').value=chosen;}apiKey=key;model=chosen;$('apiKey').value='';$('apiBtn').textContent='● Gemini 已连接';$('apiBtn').classList.add('connected');$('aiNote').textContent='已连接 '+model+'；发送后可继续描述修改。';$('apiStatus').textContent='连接成功。';$('apiDialog').close();toast('Gemini 已连接，可以描述你的灯效了');}catch(e){$('apiStatus').textContent=e.message;}finally{btn.disabled=false;}};
const sceneSchema={type:'object',properties:{summary:{type:'string'},scene:{type:'object',properties:{name:{type:'string'},duration:{type:'number'},brightness:{type:'number'},fps:{type:'integer'},layers:{type:'array',items:{type:'object',properties:{type:{type:'string',enum:TYPES},colors:{type:'array',items:{type:'string'}},cycles:{type:'integer'},scale:{type:'number'},direction:{type:'string',enum:['left','right','up','down','in','out','clockwise','counterclockwise']},space:{type:'string',enum:['local','global']},target:{type:'string'},opacity:{type:'number'}},required:['type','colors','cycles','scale','direction','space','target','opacity']}}},required:['name','duration','brightness','fps','layers']}},required:['summary','scene']};
function appendChat(cls,text){let el=document.createElement('div');el.className=cls;el.textContent=cls==='user-message'?text:t(text);$('chat').append(el);$('chat').scrollTop=$('chat').scrollHeight;return el;}
async function send(){if(busy)return;let prompt=$('prompt').value.trim();if(!prompt){toast('描述一下你想要的灯效');return;}if(!apiKey){$('apiDialog').showModal();$('apiStatus').textContent='先连接 Gemini，描述会保留。';return;}if(prompt.length>4000){toast('请将描述控制在 4000 字以内');return;}const startState=JSON.stringify(state),sceneBefore=clone(state.scene),boardSnapshot=clone(state.boards);delete sceneBefore.music;busy=true;$('sendBtn').disabled=true;$('composerStatus').textContent='Gemini 正在设计灯效…';appendChat('user-message',prompt);const responseEl=appendChat('result-message','正在把你的想法变成光…');
 try{let instruction=`You design LED scenes for a 37-pixel snowflake board, repeated ${boardSnapshot.length} times. Respond with the summary and scene.name in ${language==='en'?'English':'Simplified Chinese'}, and structured JSON scene. Modify current scene for the user's request; do not discard earlier details unless requested. Never emit code. Supported effects: ${TYPES.join(",")}. Additional effects: fire flicker, confetti random dots, scanner bouncing light band, theater discrete tri-color chase, petals six arms in turn, spiral angular plus radial waves, heartbeat double pulse, snow falling points, fireworks expanding fading ring, juggle three moving points. ${state.scene.music?"An analyzed audio track is already applied. Keep duration "+state.scene.duration+" seconds. You change visual layers only; existing music modulation is preserved.":"Audio can be added with the music panel; do not claim you generated sound."} colors 1..6 hex #rrggbb per layer. 1..6 layers additive blend, opacity 0..1. duration integer 2..30 seconds, brightness 1..100 (keep current unless explicitly requested), fps 30. cycles integer 0..12 per complete duration. scale .1..10. target 'all' or 1-based board number string. space local applies each snowflake's coordinate system; global uses positioned rotated world coords (chase uses electrical index). direction left/right/up/down/in/out/clockwise/counterclockwise. waveform periodic, brightness clamped. wave: cos^2 spatial band; breathe: sinusoidal brightness; rainbow: palette across chosen x/y axis; chase: fading tail in LED chain order; sparkle: deterministic periodic twinkle; spin: rotating angular beam; ripple: radial expansion; solid first color only. Use layers/targets for combinations. If request unsupported (new sound generation, live microphone, text, arbitrary uploaded image), explain limit in summary and approximate with supported effects without falsely claiming support. Current scene ${JSON.stringify(sceneBefore)}. Boards (positions mm): ${JSON.stringify(boardSnapshot)}. User: ${prompt}`;
 let result=await googleRequest('models/'+encodeURIComponent(model)+':generateContent',apiKey,{contents:[{role:'user',parts:[{text:instruction}]}],generationConfig:{responseMimeType:'application/json',responseJsonSchema:sceneSchema,temperature:.6,maxOutputTokens:6000}});let txt=result.candidates?.[0]?.content?.parts?.filter(p=>p.text&&!p.thought).map(p=>p.text).join('');if(!txt)throw Error('模型没有返回可用灯效，请换一种描述');let answer=JSON.parse(txt),scene=validateScene(answer.scene,boardSnapshot.length);if(JSON.stringify(state)!==startState)throw Error('生成期间项目已改变。为避免覆盖，请重新发送描述');snapshot();if(state.scene.music){scene.music=state.scene.music;scene.duration=state.scene.duration;}state.scene=scene;time=0;playing=true;playUI();changed();responseEl.replaceChildren();let title=document.createElement('b');title.textContent='✧ '+scene.name;let p=document.createElement('p');p.textContent=String(answer.summary||'灯效已更新，可以在画布中预览。').slice(0,2000);let note=document.createElement('small');note.textContent=t(`${scene.layers.length} 个灯效图层 · ${scene.duration} 秒循环 · ${scene.brightness}% 亮度`);responseEl.append(title,p,note);$('prompt').value='';
 }catch(e){responseEl.textContent=t('没有更改当前灯效：'+e.message);}finally{busy=false;$('sendBtn').disabled=false;$('composerStatus').textContent='继续描述，即可调整';$('chat').scrollTop=$('chat').scrollHeight;}}
$('sendBtn').onclick=send;$('prompt').onkeydown=e=>{if(e.key==='Enter'&&(e.ctrlKey||e.metaKey)){e.preventDefault();send();}};document.querySelectorAll('[data-prompt]').forEach(b=>b.onclick=()=>{$('prompt').value=t(b.dataset.prompt);$('prompt').focus();if(!apiKey)toast('已填入描述，连接 Gemini 后即可生成');});
document.addEventListener('keydown',e=>{if(['INPUT','TEXTAREA','SELECT'].includes(e.target.tagName)||document.querySelector('dialog[open]'))return;if((e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==='z'){e.preventDefault();e.shiftKey?redo():undo();}if(e.key==='Delete'&&selected)removeBoard();if(e.code==='Space'&&e.target.tagName!=='BUTTON'){e.preventDefault();togglePlayback();}});
$('effectName').dataset.i18nSkip='';$('musicTitle').dataset.i18nSkip='';
window.addEventListener('languagechange',syncUI);
syncUI();resize();fit();requestAnimationFrame(tick);
// Flush the pending autosave before opening the hardware viewer.
document.querySelector('.engineering-link').addEventListener('click',persistNow);

// Section shortcuts leave every editor control reachable on small screens.
document.querySelectorAll('[data-jump]').forEach(button=>button.onclick=()=>{if(button.dataset.openTab)document.querySelector(`[data-tab="${button.dataset.openTab}"]`).click();$(button.dataset.jump).scrollIntoView({behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'instant':'smooth',block:'start'});});

// Stop when leaving/backgrounding; return to an explicit sound action after interruption.
document.addEventListener('visibilitychange',()=>{if(document.hidden){if(player.clock()!==null)time=player.clock();soundEnabled=false;player.stop();soundUI();}});
window.addEventListener('pagehide',()=>player.stop());
